```jac
node GraphRoot { has name: str; }
node AgentSession { has sid: str; has issue_url: str; has slug: str; }
node SdlcTask { has tid: str; has issue_url: str; has updated_at: int; }
node Stage { has name: str; }
edge Contains {}
edge Routes {}
edge Depends {}
edge References {}

def extract_issue_number(url: str) -> str {
    if url == "" { return ""; }
    parts: list[str] = url.split("/");
    if len(parts) == 0 { return ""; }
    last: str = parts[len(parts) - 1];
    if last == "" { return ""; }
    for ch in last {
        if ch < "0" or ch > "9" { return ""; }
    }
    return last;
}

def find_session(graph_root: GraphRoot, session_id: str) -> AgentSession | None {
    sessions: list[AgentSession] = [graph_root ->:Contains:->][?:AgentSession];
    for s in sessions {
        if s.sid == session_id { return s; }
    }
    return None;
}

def find_task(graph_root: GraphRoot, task_id: str) -> SdlcTask | None {
    tasks: list[SdlcTask] = [graph_root ->:Contains:->][?:SdlcTask];
    for t in tasks {
        if t.tid == task_id { return t; }
    }
    # also check routed tasks
    sessions: list[AgentSession] = [graph_root ->:Contains:->][?:AgentSession];
    for s in sessions {
        routed: list[SdlcTask] = [s ->:Routes:->][?:SdlcTask];
        for rt in routed {
            if rt.tid == task_id { return rt; }
        }
    }
    return None;
}

walker TaskIssueWalker {
    has claimed: dict[str, bool] = {};
    has target_tid: str = "";
    has found: str = "";
    can walk_root with GraphRoot entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        sess_nodes: list[AgentSession] = [here ->:Contains:->][?:AgentSession];
        task_nodes: list[SdlcTask] = [here ->:Contains:->][?:SdlcTask];
        all_tasks: list[SdlcTask] = [];
        for s in sess_nodes {
            routed: list[SdlcTask] = [s ->:Routes:->][?:SdlcTask];
            for t in routed { all_tasks.append(t); }
        }
        for t in task_nodes { all_tasks.append(t); }
        if len(all_tasks) > 0 {
            visit :0: all_tasks;
        } else {
            if len(sess_nodes) > 0 {
                visit :0: sess_nodes;
            } else { disengage; }
        }
        print("task walker root");
    }
    can walk_session with AgentSession entry {
        if here.sid in self.claimed { skip; }
        self.claimed[here.sid] = True;
        kids: list[SdlcTask] = [here ->:Routes:->][?:SdlcTask];
        if len(kids) > 0 {
            visit :0: kids;
        } else { disengage; }
        print("task walker session");
    }
    can walk_task with SdlcTask entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        if here.tid == self.target_tid {
            self.found = extract_issue_number(here.issue_url);
            print("task issue found");
            disengage;
        }
        disengage;
        print("task walker task");
    }
}

walker ReachWalker {
    has claimed: dict[str, bool] = {};
    has collected: list[str] = [];
    can reach_stage with Stage entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        self.collected.append(here.name);
        kids: list[Stage] = [here ->:Depends:->][?:Stage];
        if len(kids) > 0 {
            visit :0: kids;
        } else { disengage; }
        print("reach stage");
    }
    can reach_root with GraphRoot entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        kids2: list[Stage] = [here ->:Contains:->][?:Stage];
        if len(kids2) > 0 {
            visit :0: kids2;
        } else { disengage; }
        print("reach root");
    }
}

walker LineageWalker {
    has claimed: dict[str, bool] = {};
    has out: list[str] = [];
    can lineage_task with SdlcTask entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        self.out.append(here.tid);
        kids: list[SdlcTask] = [here ->:References:->][?:SdlcTask];
        if len(kids) > 0 {
            visit :0: kids;
        } else { disengage; }
        print("lineage step");
    }
}

def extract_sdlc_issue_number(graph_root: GraphRoot, session_id: str, task_id: str) -> str {
    t: SdlcTask | None = find_task(graph_root, task_id);
    if t is None { return ""; }
    s: AgentSession | None = find_session(graph_root, session_id);
    if s is None { return ""; }
    w: TaskIssueWalker = graph_root spawn TaskIssueWalker(target_tid=task_id);
    if w.found != "" { return w.found; }
    tt: SdlcTask = t as SdlcTask;
    return extract_issue_number(tt.issue_url);
}

def get_reachable_stages(graph_root: GraphRoot, stage_name: str) -> list[str] {
    stages: list[Stage] = [graph_root ->:Contains:->][?:Stage];
    target: Stage | None = None;
    for st in stages {
        if st.name == stage_name { target = st; break; }
    }
    if target is None { return []; }
    tt: Stage = target as Stage;
    w: ReachWalker = tt spawn ReachWalker();
    res: list[str] = sorted(w.collected);
    return res;
}

def get_task_lineage(graph_root: GraphRoot, task_id: str) -> list[str] {
    t: SdlcTask | None = find_task(graph_root, task_id);
    if t is None { return []; }
    tt: SdlcTask = t as SdlcTask;
    w: LineageWalker = tt spawn LineageWalker();
    res: list[str] = sorted(w.out);
    return res;
}

