walker DiscoverWalker {
    has claimed: dict[str, bool] = {};
    has result: list[str] = [];
    can step with Target entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        self.result.append(here.tid);
        print(here.tid);
        kids: list[Target] = [];
        for nxt in [here ->:Depends:->][?:Target] {
            kids.append(nxt);
        }
        for nxt in [here ->:PackageProductDep:->][?:Target] {
            kids.append(nxt);
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

walker FindWalker {
    has claimed: dict[str, bool] = {};
    has target_id: str = "";
    has found: Target | None = None;
    can step with Target entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        if here.tid == self.target_id {
            self.found = here;
            print(here.tid);
            disengage;
        }
        kids: list[Target] = [];
        for nxt in [here ->:Depends:->][?:Target] {
            kids.append(nxt);
        }
        for nxt in [here ->:PackageProductDep:->][?:Target] {
            kids.append(nxt);
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def create_target(tid: str, name: str) -> Target {
    nd: Target = Target(tid=tid, name=name);
    return nd;
}

def add_dependency(src: Target, dst: Target) -> None {
    src +>:Depends:+> dst;
}

def add_package_product_dependency(src: Target, dst: Target) -> None {
    src +>:PackageProductDep:+> dst;
}

def compute_graph(graph_root: Target) -> list[str] {
    w: DiscoverWalker = graph_root spawn DiscoverWalker(claimed={}, result=[]);
    out: list[str] = [];
    for tid in w.result {
        out.append(tid);
    }
    return out;
}

def find_target(graph_root: Target, tid: str) -> Target | None {
    w: FindWalker = graph_root spawn FindWalker(claimed={}, target_id=tid, found=None);
    return w.found;
}

def compute_graph_for_id(graph_root: Target, tid: str) -> list[str] {
    if graph_root.tid == tid {
        return compute_graph(graph_root);
    }
    tgt: Target | None = find_target(graph_root, tid);
    if tgt == None {
        return [];
    }
    real: Target = tgt as Target;
    return compute_graph(real);
}

def safe_compute(graph_root: Target | None) -> list[str] {
    if graph_root == None {
        return [];
    }
    real: Target = graph_root as Target;
    return compute_graph(real);
}

