edge HasRaster {}

walker CollectRasters {
    has claimed: dict[str, bool] = {};
    has out: list[Raster] = [];
    can collect_mod with FoxyMod entry {
        if here.mid in self.claimed { skip; }
        self.claimed[here.mid] = True;
        print("collect_mod " + here.mid);
        for r in [here ->:HasRaster:->][?:Raster] {
            visit [r];
        }
        visit [] else { disengage; }
    }
    can collect_raster with Raster entry {
        if here.rid in self.claimed { skip; }
        self.claimed[here.rid] = True;
        print("collect_raster " + here.rid);
        self.out.append(here);
    }
}

walker DemoWalker {
    has claimed: dict[str, bool] = {};
    can demo_mod with FoxyMod entry {
