        print("demo_raster " + here.rid);
    }
}

def wavetable_signature(inp: str) -> str {
    # fingerprint over wavetable output - deterministic
    return inp;
}

def find_module(mid: str) -> FoxyMod | None {
    for m in [root -->][?:FoxyMod] {
        if m.mid == mid {
            return m;
        }
    }
    return None;
}

def create_module(mid: str) -> FoxyMod {
    mod: FoxyMod = FoxyMod(mid=mid);
    root ++> mod;
    return mod;
}

def add_raster(mod: FoxyMod, rid: str, sig: str) -> Raster {
    r: Raster = Raster(rid=rid, sig=sig);
    mod +>:HasRaster:+> r;
    return r;
}

def set_frozen(r: Raster, on: bool) -> bool {
    r.frozen = on;
    return True;
}

def update_raster_sig(r: Raster, sig: str) -> bool {
    r.sig = sig;
    return True;
}

def set_quiesce(mid: str, on: bool) -> bool {
    mod: FoxyMod | None = find_module(mid);
    if mod is None {
        return False;
    }
    mod_ok: FoxyMod = mod as FoxyMod;
    mod_ok.quiesced = on;
    return True;
}

def bridge_tick(mid: str) -> dict[str, int] {
    mod: FoxyMod | None = find_module(mid);
    if mod is None {
        out: dict[str, int] = {};
        out["painted"] = 0;
        out["field_built"] = 0;
        out["skipped"] = 1;
        out["sig"] = 0;
        return out;
    }
    mod_ok: FoxyMod = mod as FoxyMod;
    if mod_ok.quiesced and mod_ok.tick_count > 0 {
        mod_ok.tick_count += 1;
        res: dict[str, int] = {};
        res["painted"] = 0;
        res["field_built"] = 0;
        res["skipped"] = 1;
        res["sig"] = len(mod_ok.cached_output_sig);
        return res;
    }
    w: CollectRasters = mod_ok spawn CollectRasters();
    rasters: list[Raster] = w.out;
    inp: str = "";
    for r in rasters {
        inp += r.sig;
    }
    if mod_ok.cached_input_sig != "" and inp == mod_ok.cached_input_sig {
        mod_ok.tick_count += 1;
        res2: dict[str, int] = {};
        res2["painted"] = 0;
        res2["field_built"] = 0;
        res2["skipped"] = 1;
        res2["sig"] = len(mod_ok.cached_output_sig);
        return res2;
    }
    sig_str: str = wavetable_signature(inp);
    mod_ok.cached_input_sig = inp;
    mod_ok.cached_output_sig = sig_str;
    mod_ok.tick_count += 1;
    out3: dict[str, int] = {};
    out3["painted"] = 3;
    out3["field_built"] = 1;
    out3["skipped"] = 0;
    out3["sig"] = len(sig_str);
    return out3;
}

