```jac
node ExplorerRoot { has name: str; }
node Experiment { has exp_id: str; has seed: int; }
node BenchCell { has cell_id: str; has score: float; has cost: float; has status: str; has source: str; has mutation: str = ""; }
node Arch { has arch_id: str; has config: str; has params: int; }
edge Owns {}
edge Lineage {}
edge HasCell {}
edge Depends {}
edge ArchLink {}

walker LineageClosure {
    has claimed: dict[str, bool] = {};
    has collected: list[str] = [];
    can step_exp with Experiment entry {
        if here.exp_id in self.claimed { skip; }
        self.claimed[here.exp_id] = True;
        self.collected.append(here.exp_id);
        print(here.exp_id);
        for nxt in [here ->:Lineage:->][?:Experiment] {
            visit :0: [nxt];
        }
    }
}

walker ScanCells {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    has failed: list[str] = [];
    can scan_exp with Experiment entry {
        if here.exp_id in self.claimed { skip; }
        self.claimed[here.exp_id] = True;
        print(here.exp_id);
        for c in [here ->:HasCell:->][?:BenchCell] {
            visit :0: [c];
        }
        for nxt in [here ->:Lineage:->][?:Experiment] {
            visit :0: [nxt];
        }
    }
    can scan_cell with BenchCell entry {
        if here.cell_id in self.claimed { skip; }
        self.claimed[here.cell_id] = True;
        self.found.append(here.cell_id);
        if here.status == "failed" or here.status == "unsupported" {
            self.failed.append(here.cell_id);
        }
        print(here.cell_id);
        for dep in [here ->:Depends:->][?:BenchCell] {
            visit :0: [dep];
        }
    }
}

def find_experiment(root_node: ExplorerRoot, exp_id: str) -> Experiment | None {
    for cand in [root_node ->:Owns:->][?:Experiment] {
        if cand.exp_id == exp_id { return cand; }
    }
    return None;
}

def find_cell(root_node: ExplorerRoot, cell_id: str) -> BenchCell | None {
    for ex in [root_node ->:Owns:->][?:Experiment] {
        for c in [ex ->:HasCell:->][?:BenchCell] {
            if c.cell_id == cell_id { return c; }
        }
    }
    return None;
}

def find_arch(root_node: ExplorerRoot, arch_id: str) -> Arch | None {
    for a in [root_node ->:Owns:->][?:Arch] {
        if a.arch_id == arch_id { return a; }
    }
    return None;
}

def make_explorer(name: str) -> ExplorerRoot {
    g: ExplorerRoot = ExplorerRoot(name=name);
    return g;
}

def add_experiment(root_node: ExplorerRoot, exp_id: str, seed: int) -> Experiment | None {
    # bounded deterministic identifier check
    if find_experiment(root_node, exp_id) != None { return None; }
    nd: Experiment = Experiment(exp_id=exp_id, seed=seed);
    root_node +>:Owns:+> nd;
    return nd;
}

def add_arch(root_node: ExplorerRoot, arch_id: str, config: str, params: int) -> Arch | None {
    if find_arch(root_node, arch_id) != None { return None; }
    nd: Arch = Arch(arch_id=arch_id, config=config, params=params);
    root_node +>:Owns:+> nd;
    return nd;
}

def add_cell(root_node: ExplorerRoot, exp_id: str, cell_id: str, score: float, cost: float, status: str, source: str) -> BenchCell | None {
    ex = find_experiment(root_node, exp_id);
    if ex == None { return None; }
    cand = ex as Experiment;
    if find_cell(root_node, cell_id) != None { return None; }
    c: BenchCell = BenchCell(cell_id=cell_id, score=score, cost=cost, status=status, source=source);
    cand +>:HasCell:+> c;
    return c;
}

def add_lineage(root_node: ExplorerRoot, parent_id: str, child_id: str) -> bool {
    p = find_experiment(root_node, parent_id);
    ch = find_experiment(root_node, child_id);
    if p == None or ch == None { return False; }
    pp = p as Experiment; cc = ch as Experiment;
    pp +>:Lineage:+> cc;
    return True;
}

def add_dependency(root_node: ExplorerRoot, from_id: str, to_id: str) -> bool {
    a = find_cell(root_node, from_id);
    b = find_cell(root_node, to_id);
    if a == None or b == None { return False; }
    aa = a as BenchCell; bb = b as BenchCell;
    aa +>:Depends:+> bb;
    return True;
}

def get_lineage(root_node: ExplorerRoot, exp_id: str) -> list[str] {
    st = find_experiment(root_node, exp_id);
    if st == None { return []; }
    s = st as Experiment;
    w = s spawn LineageClosure();
    return w.collected;
}

def get_failures(root_node: ExplorerRoot) -> list[str] {
    res: list[str] = [];
    for ex in [root_node ->:Owns:->][?:Experiment] {
        w = ex spawn ScanCells();
        for f in w.failed { res.append(f); }
    }
    return sorted(res);
}

def get_pareto_front(root_node: ExplorerRoot) -> list[str] {
    # collect all cells via walker
    all_ids: list[str] = [];
    for ex in [root_node ->:Owns:->][?:Experiment] {
        w = ex spawn ScanCells();
        for fid in w.found { all_ids.append(fid); }
    }
    # dedup
    uniq: dict[str, bool] = {};
    cells: list[BenchCell] = [];
    for cid in all_ids {
        if cid in uniq { continue; }
        uniq[cid] = True;
        c = find_cell(root_node, cid);
        if c != None {
            cc = c as BenchCell;
            if cc.status == "supported" {
                cells.append(cc);
            }
        }
    }
    front: list[str] = [];
    for cand in cells {
        dominated: bool = False;
        for other in cells {
            if other.cell_id == cand.cell_id { continue; }
            if other.score >= cand.score and other.cost <= cand.cost {
                if other.score > cand.score or other.cost < cand.cost {
                    dominated = True;
                    break;
                }
            }
        }
        if dominated == False { front.append(cand.cell_id); }
    }
    return sorted(front);
}

def diff_architectures(root_node: ExplorerRoot, arch_a: str, arch_b: str) -> dict[str, str] {
    a = find_arch(root_node, arch_a);
    b = find_arch(root_node, arch_b);
    out: dict[str, str] = {};
    if a == None or b == None {
        out["error"] = "unknown";
        return out;
    }
    aa = a as Arch; bb = b as Arch;
    if aa.config == bb.config { out["config"] = "same"; } else { out["config"] = "diff"; }
    if aa.params == bb.params { out["params"] = "same"; } else { out["params"] = "diff"; }
    out["arch_a"] = aa.arch_id;
    out["arch_b"] = bb.arch_id;
    return out;
}

def explain_mutation(root_node: ExplorerRoot, cell_id: str) -> str {
    c = find_cell(root_node, cell_id);
    if c == None { return "unknown"; }
    cc = c as BenchCell;
    if cc.mutation == "" { return "none"; }
    return cc.mutation;
}

with entry {
    demo: ExplorerRoot = ExplorerRoot(name="v19-demo");
    root ++> demo;
    add_experiment(demo, "e0", 42);
    add_experiment(demo, "e1", 43);
    add_lineage(demo, "e0", "e1");
    w = demo spawn ScanCells();
    print(w.found);
    r2 = root spawn LineageClosure();
    print(r2.collected);
}
