```jac
node AuditRoot { has marker: str; }
node StateMachine { has mid: str; has lane: str; has frozen: bool = False; }
node State { has sid: str; has terminal: bool = False; has stale_binding: bool = False; }
node Finding { has fid: str; has impact: int = 0; has reachable: bool = False; }
edge Contains {}
edge Transition { has guard: str = ""; has idempotent: bool = True; }
edge Flags {}

walker InventoryWalker {
    has claimed: dict[str, bool] = {};
    has result: list[str] = [];
    can collect_root with AuditRoot entry {
        if here.marker in self.claimed { skip; }
        self.claimed[here.marker] = True;
        print("inventory root " + here.marker);
        kids: list[StateMachine] = [here ->:Contains:->][?:StateMachine];
        if kids { visit :0: kids; } else { disengage; }
    }
    can collect_machine with StateMachine entry {
        if here.mid in self.claimed { skip; }
        self.claimed[here.mid] = True;
        print("seen machine " + here.mid);
        if here.frozen == False {
            if here.lane != "consensus" {
                if here.lane != "src/node_core.ts" {
                    self.result.append(here.mid);
                }
            }
        }
        kids: list[State] = [here ->:Contains:->][?:State];
        if kids { visit :0: kids; } else { disengage; }
    }
    can collect_state with State entry {
        if here.sid in self.claimed { skip; }
        self.claimed[here.sid] = True;
        print("seen state " + here.sid);
        disengage;
    }
}

walker ReachWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    can reach_state with State entry {
        if here.sid in self.claimed { skip; }
        self.claimed[here.sid] = True;
        self.found.append(here.sid);
        print("reach " + here.sid);
        nxt: list[State] = [here ->:Transition:->][?:State];
        if nxt { visit :0: nxt; } else { disengage; }
    }
}

walker FinderWalker {
    has claimed: dict[str, bool] = {};
    has target: str = "";
    has out: State | None = None;
    can find_root with AuditRoot entry {
        if here.marker in self.claimed { skip; }
        self.claimed[here.marker] = True;
        print("finder root");
        kids: list[StateMachine] = [here ->:Contains:->][?:StateMachine];
        if kids { visit :0: kids; } else { disengage; }
    }
    can find_machine with StateMachine entry {
        if here.mid in self.claimed { skip; }
        self.claimed[here.mid] = True;
        print("finder machine " + here.mid);
        kids: list[State] = [here ->:Contains:->][?:State];
        if kids { visit :0: kids; } else { disengage; }
    }
    can find_state with State entry {
        if here.sid in self.claimed { skip; }
        self.claimed[here.sid] = True;
        print("finder state " + here.sid);
        if here.sid == self.target { self.out = here; }
        nxt: list[State] = [here ->:Transition:->][?:State];
        if nxt { visit :0: nxt; } else { disengage; }
    }
}

walker RankWalker {
    has claimed: dict[str, bool] = {};
    has ranked: list[str] = [];
    can rank_root with AuditRoot entry {
        if here.marker in self.claimed { skip; }
        self.claimed[here.marker] = True;
        print("rank root");
        fnds: list[Finding] = [here ->:Flags:->][?:Finding];
        if fnds { visit :0: fnds; } else { disengage; }
    }
    can rank_finding with Finding entry {
        if here.fid in self.claimed { skip; }
        self.claimed[here.fid] = True;
        print("rank fid " + here.fid);
        if here.reachable { self.ranked.append(here.fid); }
        disengage;
    }
}

def build_audit(marker: str) -> AuditRoot { rt = AuditRoot(marker=marker); return rt; }
def add_state_machine(graph_root: AuditRoot, mid: str, lane: str, frozen: bool) -> StateMachine {
    sm = StateMachine(mid=mid, lane=lane, frozen=frozen);
    graph_root +>:Contains:+> sm;
    return sm;
}
def add_state(machine: StateMachine, sid: str, terminal: bool, stale_binding: bool) -> State {
    st = State(sid=sid, terminal=terminal, stale_binding=stale_binding);
    machine +>:Contains:+> st;
    return st;
}
def add_transition(src: State, dst: State, guard: str) -> None {
    src +>:Transition:+> dst;
}
def add_finding(graph_root: AuditRoot, fid: str, impact: int, reachable: bool) -> Finding {
    f = Finding(fid=fid, impact=impact, reachable=reachable);
    graph_root +>:Flags:+> f;
    return f;
}
def inventory_high_risk(graph_root: AuditRoot) -> list[str] {
    w = graph_root spawn InventoryWalker();
    return sorted(w.result);
}
def reachable_states(graph_root: AuditRoot, start_sid: str) -> list[str] {
    fw = graph_root spawn FinderWalker(target=start_sid);
    # second spawn to reuse target because jac walkers need init via spawn arg not available, so set after
    fw.target = start_sid;
    # re-run if not found due to ordering: use finder walk again
    found: State | None = fw.out;
    if found is None {
        # fallback linear scan via finder already did full closure; if still none return empty
        return [];
    }
    rw = found spawn ReachWalker();
    return sorted(rw.found);
}
def rank_findings(graph_root: AuditRoot) -> list[str] {
    w = graph_root spawn RankWalker();
    return sorted(w.ranked);
}

