        if here.pid in self.claimed { skip; }
        self.claimed[here.pid] = True;
        if not here.isTrashed {
            here.isTrashed = True;
            here.trashedAt = "now";
        }
        self.result.append(here.pid);
        print(here.pid);
        kids: list[Page] = [here ->:Parent:->][?:Page];
        visit :0: kids else { disengage; }
