test "diamond_revisit_reachability" {
    anchor = make_anchor("t1");
    m = register_machine(anchor, "sm1", "worker", False, False);
    a = add_state(m, "A", False);
    b = add_state(m, "B", False);
    c = add_state(m, "C", False);
    d = add_state(m, "D", True);
    # diamond: A -> B, A -> C, B -> D, C -> D  insertion order forces revisit before deeper
    add_transition(a, b);
    add_transition(a, c);
    add_transition(b, d);
    add_transition(c, d);
    # reachable from A should be exactly A,B,C,D once each
    got = reachable_from(m, "A");
    assert(sorted(got) == sorted(["A", "B", "C", "D"]));;
    # full machine reach should also be same set (all states reachable via Contains)
    all = reachable_states(m);
    assert(sorted(all) == sorted(["A", "B", "C", "D"]));;
}

test "rank_filters_unreachable_and_occupied" {
    anchor = make_anchor("t2");
    m1 = register_machine(anchor, "m1", "worker", False, False);
    m2 = register_machine(anchor, "m2", "consensus", True, False);
    m3 = register_machine(anchor, "m3", "worker", False, False);
    m_frozen = register_machine(anchor, "mf", "worker", False, True);
    add_finding(m1, "F1", 10, True, True);
    add_finding(m1, "F2", 9, False, True);
    add_finding(m3, "F3", 8, True, False);
    add_finding(m2, "F4", 100, True, True);
    add_finding(m_frozen, "F5", 100, True, True);
    rk = rank_findings(anchor);
    assert(sorted(rk) == sorted(["F1", "F3"]));;
    # impact ordering: F1 (10) before F3 (8)
    assert(rk[0] == "F1");;
    assert(rk[1] == "F3");;
}

test "unknown_id_tolerance" {
    anchor = make_anchor("t3");
    m = register_machine(anchor, "sm1", "worker", False, False);
    s = add_state(m, "A", False);
    # unknown start sid returns empty not error
    empty = reachable_from(m, "NOPE");
    assert(len(empty) == 0);;
    # unknown anchor has no findings
    empty_anchor = make_anchor("empty");
    rk2 = rank_findings(empty_anchor);
    assert(len(rk2) == 0);;
    # add duplicate transition is idempotent, reach still correct
    add_transition(s, s);
    got2 = reachable_from(m, "A");
    assert(got2 == ["A"]);;
}

test "cycle_and_terminal_closure" {
    anchor = make_anchor("t4");
    m = register_machine(anchor, "sm1", "worker", False, False);
    a = add_state(m, "A", False);
    b = add_state(m, "B", False);
    c = add_state(m, "C", True);
    # cycle A -> B -> A plus B -> C terminal
    add_transition(a, b);
    add_transition(b, a);
    add_transition(b, c);
    got = reachable_from(m, "A");
    assert(sorted(got) == sorted(["A", "B", "C"]));;
    # terminal state has no outgoing
    got_c = reachable_from(m, "C");
    assert(got_c == ["C"]);;
}
