test "diamond_lineage_revisit_adversarial" {
    r = Runtime(rid="r1");
    root ++> r;
    assert (create_task(r, "a"));
    assert (create_task(r, "b"));
    assert (create_task(r, "c"));
    assert (create_task(r, "d"));
    # adversarial insertion order: d depends on b,c ; b,c depend on a
    # so walker from d will hit a via both paths, revisit must be skipped not disengaged
    assert (link_task_parent(r, "b", "a"));
    assert (link_task_parent(r, "c", "a"));
    assert (link_task_parent(r, "d", "b"));
    assert (link_task_parent(r, "d", "c"));
    got = get_task_lineage(r, "d");
    assert (sorted(got) == ["a", "b", "c", "d"]);
    # second walk from b should be subset, proves closure not truncated by prior claim
    got2 = get_task_lineage(r, "b");
    assert (sorted(got2) == ["a", "b"]);
}

test "provenance_diamond_and_unknown_id" {
    r = Runtime(rid="r2");
