    pv: list[int] = parse_ver(version);
    if len(pv) == 0 or len(pc) == 0 { return False; }
    if pv[0] != pc[0] { return False; }
    if cmp_ver(pv, pc) < 0 { return False; }
    return True;
}

def dry_run_plan(root_name: str, versions: dict[str, str], dep_map: dict, installed: dict, offline: bool) -> dict {
    graph_root: GraphRoot = GraphRoot();
    nodes: dict[str, Pkg] = {};
    dep_constraints: dict[str, str] = {};
    for k in versions {
        vv: str = versions[k];
        nd: Pkg = Pkg(name=k, version=vv);
        nodes[k] = nd;
        graph_root ++> nd;
    }
    for parent in dep_map {
        if parent not in nodes { continue; }
        par: Pkg = nodes[parent];
        lst: list = dep_map[parent];
        for entry in lst {
            dep_name: str = entry["name"];
            constraint: str = "";
            if "constraint" in entry {
                constraint = entry["constraint"];
            } else {
                if "version" in entry { constraint = entry["version"]; }
            }
            dep_constraints[dep_name] = constraint;
            child: Pkg = nodes[dep_name] if dep_name in nodes else Pkg(name=dep_name, version="0.0.0");
            if dep_name not in nodes {
                nodes[dep_name] = child;
                graph_root ++> child;
            } else {
                child = nodes[dep_name];
            }
            # definite instances narrow optional already
            par +>:Depends(constraint=constraint):+> child;
        }
    }
    if root_name not in nodes {
        res: dict[str, object] = {};
        res["execution_order"] = [];
        res["satisfied_dependencies"] = [];
        res["installed_state_evaluated"] = not offline;
        res["execution_order_is_provisional"] = offline;
        res["plans"] = {};
        return res;
    }
    root_pkg: Pkg = nodes[root_name];
    # normalized installed for case-insensitive lookup
    norm_installed: dict[str, dict] = {};
    for ik in installed {
        up: str = ik.upper();
        norm_installed[up] = installed[ik];
        norm_installed[ik] = installed[ik];
    }
    w: Closure = root_pkg spawn Closure(claimed={});
    closure: list[Pkg] = w.found;
    satisfied: list[dict] = [];
    need: list[Pkg] = [];
    need_names: dict[str, bool] = {};
    plans: dict[str, dict] = {};
    for pkg in closure {
        cstr: str = "";
        if pkg.name in dep_constraints { cstr = dep_constraints[pkg.name]; }
        is_root: bool = pkg.name == root_name;
        installed_hit: bool = False;
        inst_info: dict = {};
        lookup: str = pkg.name.upper();
        if lookup in norm_installed { installed_hit = True; inst_info = norm_installed[lookup]; }
        do_satisfy: bool = False;
        if not offline and installed_hit and not is_root {
            iv: str = inst_info["version"];
            ds: str = "";
            if "deploy_status" in inst_info { ds = inst_info["deploy_status"]; }
            if ds == "C" and satisfies(iv, cstr) { do_satisfy = True; }
        }
        if do_satisfy {
            satisfied.append({"application_name": pkg.name, "installed_state": inst_info});
            plans[pkg.name] = {"installed_state": inst_info, "mode": "satisfied"};
        } else {
            need.append(pkg);
            need_names[pkg.name] = True;
            if installed_hit and not offline {
                plans[pkg.name] = {"installed_state": inst_info, "mode": "install"};
            } else {
                plans[pkg.name] = {"installed_state": None, "mode": "install"};
            }
        }
    }
    # topological order: dependencies before dependents
    execution_order: list[str] = [];
    placed: dict[str, bool] = {};
    # deterministic tie-break: sort need by name initially
    # simple bubble sort via sorted
    # use sorted names to iterate
    guard: int = 0;
    while len(execution_order) < len(need) {
        progressed: bool = False;
        for pkg in need {
            if pkg.name in placed { continue; }
            deps: list[Pkg] = [pkg ->:Depends:->][?:Pkg];
            all_done: bool = True;
            for d in deps {
                if d.name in need_names {
                    if d.name not in placed { all_done = False; break; }
                }
            }
            if all_done {
                execution_order.append(pkg.name);
                placed[pkg.name] = True;
                progressed = True;
            }
        }
        if not progressed { break; }
        guard = guard + 1;
        if guard > 100 { break; }
    }
    out: dict[str, object] = {};
    out["execution_order"] = execution_order;
    out["satisfied_dependencies"] = satisfied;
    out["installed_state_evaluated"] = not offline;
    out["execution_order_is_provisional"] = offline;
    out["plans"] = plans;
    return out;
}

