def render_offline_html(graph_root: Report, include_snippets: bool) -> str {
    if graph_root.rid == "" or graph_root.bounded_context == "" {
        return "<html><body><div class=\"error\">malformed report: missing rid or context</div></body></html>";
    }
    if graph_root.run_hash == "" {
        return "<html><body><div class=\"error\">malformed report: missing run_hash</div></body></html>";
    }
    html: str = "<html><head><style>body{font-family:sans-serif}</style></head><body><div id=\"metadata\" data-rid=\"" + graph_root.rid + "\" data-context=\"" + graph_root.bounded_context + "\" data-hash=\"" + graph_root.run_hash + "\"></div><section id=\"architecture\">";
    ents: list[Entity] = [];
    ids: list[str] = [];
    for ent in [graph_root ->:Contains:->][?:Entity] { ents.append(ent); ids.append(ent.eid); }
    ids = sorted(ids);
    for eid in ids {
        target: Entity | None = None;
        for ent in ents { if ent.eid == eid { target = ent; } }
        if target != None {
            e = target as Entity;
            html = html + "<div class=\"entity\" id=\"" + stable_anchor("entity", e.eid) + "\" data-kind=\"" + e.kind + "\" data-path=\"" + e.path + "\" data-lines=\"" + str(e.line_start) + "-" + str(e.line_end) + "\" data-hash=\"" + e.hash_val + "\" data-provenance=\"" + e.provenance + "\" data-status=\"" + e.status + "\">" + e.eid + "</div>";
        }
    }
    html = html + "</section><section id=\"relations\">";
    for ent in ents {
        for dep in [ent ->:Depends:->][?:Entity] {
            html = html + "<a class=\"relation\" href=\"#" + stable_anchor("entity", ent.eid) + "\" data-target=\"" + stable_anchor("entity", dep.eid) + "\">" + ent.eid + "->" + dep.eid + "</a>";
        }
    }
    html = html + "</section><section id=\"diagnostics\">";
    diags: list[Diagnostic] = [];
    dids: list[str] = [];
    for d in [graph_root ->:Contains:->][?:Diagnostic] { diags.append(d); dids.append(d.did); }
    dids = sorted(dids);
    for did in dids {
        target2: Diagnostic | None = None;
        for d in diags { if d.did == did { target2 = d; } }
        if target2 != None {
            d = target2 as Diagnostic;
            html = html + "<div class=\"diagnostic\" id=\"" + stable_anchor("diag", d.did) + "\" data-severity=\"" + d.severity + "\" data-status=\"" + d.status + "\" data-analyzer=\"" + d.analyzer + "\" data-entity=\"" + d.entity_ref + "\">" + d.did + "<a href=\"#" + stable_anchor("entity", d.entity_ref) + "\">entity</a></div>";
            for ev in [d ->:EvLink:->][?:Evidence] {
                html = html + "<div class=\"evidence\" data-path=\"" + ev.path + "\" data-lines=\"" + str(ev.line_start) + "-" + str(ev.line_end) + "\" data-hash=\"" + ev.hash_val + "\">";
                if include_snippets { html = html + "<pre>" + ev.snippet + "</pre>"; }
                html = html + "</div>";
            }
        }
    }
    html = html + "</section><section id=\"coverage\"><div class=\"unknown\">unknown</div><div class=\"not-analyzed\">not-analyzed</div></section><section id=\"filters\" data-filters=\"severity,provenance,status,analyzer,entity,relation\"></section></body></html>";
    return html;
}

