test "diamond upstream is set independent of insertion order" {
    rpt = create_report("r1", "h1");
    add_package(rpt, "pkgA", "a", "code");
    add_package(rpt, "pkgB", "b", "code");
    add_package(rpt, "pkgC", "c", "code");
    add_package(rpt, "pkgD", "d", "code");
    # diamond: A->B, A->C, B->D, C->D but inserted adversarially C edge before B
    add_relation(rpt, "rAC", "depends", "pkgA", "pkgC");
    add_relation(rpt, "rAB", "depends", "pkgA", "pkgB");
    add_relation(rpt, "rCD", "depends", "pkgC", "pkgD");
    add_relation(rpt, "rBD", "depends", "pkgB", "pkgD");
    up = get_upstream(rpt, "pkgD");
    assert(sorted(up) == ["pkgA", "pkgB", "pkgC", "pkgD"]);
    down = get_downstream(rpt, "pkgA");
    assert(sorted(down) == ["pkgA", "pkgB", "pkgC", "pkgD"]);
}
